                // v1.2.0: the next Chinese order arrives 45 days late; safety stock covers part of the gap on
                // the share still bought in China (TN 372 divergence 1; concept: 30 days of stock, 15 days short)
                var alBrazil = ds.aluminumBrazilPct || 0;
                var chinaShare = Math.max(0, 100 - alBrazil);
                var ss = ds.safetyStockDays || 38;
                var disruptionDays = Math.round(chinaShare / 100 * Math.max(0, 45 - ss));
                ds.disruptionDays = disruptionDays;
                ds.customerSatisfaction -= disruptionDays;

                var productionLossPerDay = 16.1;
                var disruptionCost = 0;

                if (d.crisisResponse === 'emergency') {
                    disruptionCost = disruptionDays * productionLossPerDay * 0.3 + disruptionDays * 8.5;
                    ds.customerSatisfaction -= 5;
                } else if (d.crisisResponse === 'ration') {
                    disruptionCost = disruptionDays * productionLossPerDay * 0.6;
                    ds.customerSatisfaction -= 10;
                } else {
                    disruptionCost = disruptionDays * productionLossPerDay * 0.8;
                    ds.customerSatisfaction -= 15;
                }

                var devalImpact = ds.usdExposure * 0.22 * 480;
                var priceRecovery = 0;

                if (d.priceStrategy === 'immediate') {
                    priceRecovery = devalImpact * 0.85;
                    ds.customerSatisfaction -= 12;
                } else if (d.priceStrategy === 'gradual') {
                    priceRecovery = devalImpact * 0.55;
                    ds.customerSatisfaction -= 4;
                } else {
                    priceRecovery = devalImpact * 0.70;
                    ds.customerSatisfaction -= 2;
                }

                var netDevalCost = Math.round(devalImpact - priceRecovery);
                var totalCrisisCost = Math.round(disruptionCost + netDevalCost);
                ds.ebitda = Math.max(500, ds.ebitda - totalCrisisCost);
                ds.crisisImpact = totalCrisisCost;

                if (ds.customerSatisfaction < 20) ds.customerSatisfaction = 20;

                results.disruptionDays = disruptionDays;
                results.disruptionCost = Math.round(disruptionCost);
                results.devalImpact = Math.round(devalImpact);
                results.priceRecovery = Math.round(priceRecovery);
                results.netCrisisCost = totalCrisisCost;
                results.customerSatisfaction = ds.customerSatisfaction;
                results.usdExposure = ds.usdExposure;
                results.ebitda = ds.ebitda;

                // v1.2.0: no shortage scores as well as a short one handled well; the crisis response
                // scores only when there is a shortage to manage (TN 372 section 13.1 item 7)
                var score = 0;
                if (disruptionDays === 0) score += 30;
                else if (disruptionDays <= 3) score += 20;
                else if (disruptionDays <= 8) score += 10;
                if (d.priceStrategy === 'differentiated') score += 15;
                else if (d.priceStrategy === 'gradual') score += 10;
                if (disruptionDays > 0 && d.crisisResponse === 'emergency') score += 10;
                else if (disruptionDays > 0 && d.crisisResponse === 'ration') score += 8;
                if (ds.customerSatisfaction >= 60) score += 10;

                results.roundScore = score;

            } else if (period === 4) {
                var usdReduction4 = 0;
                var ebitdaChange = 0;

                var acqFunded = ds.budgetRemaining >= 3200;
                ds.acquired = d.acquisition === 'yes';
                ds.acqFunded = ds.acquired && acqFunded;
                if (d.acquisition === 'yes') {
                    ds.budgetRemaining -= 3200;
                    ebitdaChange += Math.round(12400 * 0.06);
                    if (ds.inkOption === 'D') {
                        usdReduction4 += 3;
                    } else {
                        usdReduction4 += 5;
                    }
                    ds.customerSatisfaction += 5;
                }

                if (d.usdLever === 'financial') {
                    usdReduction4 += 4;
                    ebitdaChange -= 180;
                } else if (d.usdLever === 'operational') {
                    usdReduction4 += 6;
                    ebitdaChange -= 350;
                } else {
                    usdReduction4 += 8;
                    ebitdaChange += 200;
                }

                ds.usdExposure = Math.max(30, Math.round((ds.usdExposure - usdReduction4) * 10) / 10);
                ds.ebitda += ebitdaChange;
                if (ds.ebitda < 500) ds.ebitda = 500;

                results.finalUsdExposure = ds.usdExposure;
                results.usdReduction = Math.round(usdReduction4 * 10) / 10;
                results.ebitdaChange = ebitdaChange;
                results.customerSatisfaction = ds.customerSatisfaction;
                results.targetAchieved = ds.usdExposure <= 50;
                results.usdExposure = ds.usdExposure;
                results.ebitda = ds.ebitda;

                var score = 0;
                if (ds.usdExposure <= 50) score += 25;
                else if (ds.usdExposure <= 55) score += 15;
                else score += 5;
                if (ds.customerSatisfaction >= 65) score += 10;
                // v1.2.0: an acquisition the budget cannot pay for earns nothing, and the plan must stay
                // within its budget as in Round 2 (TN 372 section 13.1 item 5)
                if (d.acquisition === 'yes' && !acqFunded) score += 0;
                else if (d.acquisition === 'yes' && ds.inkOption !== 'D') score += 15;
                else if (d.acquisition === 'yes') score += 8;
                else score += 5;
                if (ds.budgetRemaining >= 0) score += 15;
                if (d.usdLever === 'commercial') score += 10;
                else if (d.usdLever === 'operational') score += 8;
                else score += 5;

                results.roundScore = score;
            }

            ds.usdExposureHistory.push(ds.usdExposure);
            ds.ebitdaHistory.push(ds.ebitda);
            ds.scoreHistory.push(results.roundScore || 0);

            // v1.1.0 FIX: persist a normalized 0-100 score into domainState so the
            // grading/reporting layer can read it. results_utils.php
            // (express_resolveDomainScore) reads domainState.performance.overallScore
            // (a normalized 0-100 grade) first, then top-level domainState.score.
            // The sim previously only tracked a per-round sum out of 110
            // (getPerformanceSummary.maxPossibleScore) and wrote no resolvable field,
            // so the instructor results panel showed an empty score.
            // v1.2.0: normalised by the points the rounds played so far can award, so the grade
            // no longer saturates (TN 372 section 13.1 item 3); band and label come from one helper
            var _ov = this._overall(ds.scoreHistory);
            ds.performance = { overallScore: _ov, grade: this._band(_ov), tier: this._band(_ov) };
            ds.score = _ov;
            results.overallScore = _ov;

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._showRoundResults(state, results);
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            return results;
        }

        _lang() {
            var l = '';
            try { if (window.vcI18n && window.vcI18n._lang) l = window.vcI18n._lang; } catch (e) {}
            if (!l) l = (document.documentElement.lang || 'en');
            return String(l).slice(0, 2).toLowerCase();
        }

        _fmt(v) {
            var n = Number(v);
            if (!isFinite(n)) return String(v);
            var str = (Math.round(n * 10) / 10).toLocaleString('en-US');
            if (this._lang() === 'es') str = str.replace(/,/g, '#').replace(/[.]/g, ',').replace(/#/g, '.');
            return str;
        }

        _tf(key, vals) {
            var txt = window.mySimulation && window.mySimulation.t ? window.mySimulation.t(key) : key;
            for (var k in vals) { if (Object.prototype.hasOwnProperty.call(vals, k)) txt = txt.split('{' + k + '}').join(String(vals[k])); }
            return txt;
        }

        _aluPremiumArs(brazilPct) {
            // net annual premium of Brazilian film in ARS M: price gap minus logistics and management savings
            var pct = Math.max(0, Math.min(100, brazilPct || 0));
            var priceDelta = (5100 - 4200) * 250 / 1000 * pct / 100;
            var savings = (41.6 + 5.2 + 8.4) * pct / 100;
            return Math.round((priceDelta - savings) * 1.025);
        }

        _overall(scores) {
            var got = 0, max = 0;
            for (var i = 0; i < scores.length && i < this.ROUND_MAX.length; i++) { got += scores[i] || 0; max += this.ROUND_MAX[i]; }
            if (!max) return 0;
            return Math.max(0, Math.min(100, Math.round(got / max * 1000) / 10));
        }

        _band(score) {
            if (score >= 85) return 'expert';
            if (score >= 70) return 'proficient';
            if (score >= 50) return 'developing';
            return 'beginner';
        }

        _showRoundResults(state, results) {
            var panel = document.getElementById('roundResultsPanel');
            var text = document.getElementById('roundResultsText');
            if (!panel || !text) return;
