                html += '<br>' + window.mySimulation.t('aluminum_cost_delta') + ': USD ' + results.aluminumCostDelta + 'K' + window.mySimulation.t('unit_per_year');
                html += '<br>' + window.mySimulation.t('tco_savings') + ': USD ' + results.tcoSavings + 'K' + window.mySimulation.t('unit_per_year');
                html += '<br>' + window.mySimulation.t('alu_ebitda_impact') + ': ARS ' + results.aluEbitdaImpact + 'M';
                html += '<br>' + window.mySimulation.t('new_lead_time') + ': ' + results.newLeadTime + ' ' + window.mySimulation.t('unit_days');
            } else if (period === 2) {
