        getPerformanceSummary(history) {
            if (!history.length) return {};
            var scores = history.map(function(r) { return r.results && r.results.roundScore ? r.results.roundScore : 0; });
            var totalScore = scores.reduce(function(s, v) { return s + v; }, 0);
            var lastState = history[history.length - 1];
            var finalExposure = lastState.results ? lastState.results.usdExposure || 72 : 72;
            var finalEbitda = lastState.results ? lastState.results.ebitda || 8230 : 8230;
            var targetAchieved = finalExposure <= 50;

            var overall = this._overall(scores);
            var tier = this._band(overall);
            var performance = window.mySimulation && window.mySimulation.t ? window.mySimulation.t('tier_' + tier) : tier;

            // v1.2.0: insights built from this run's history; the turning point names the first
            // mistake the run made (EQIL 14 item 13, S4), in words the other insights do not use
            var self = this;
            var ds = lastState.domainState || {};
            var tt = function(k, v) { return self._tf(k, v); };
            var mistakes = [];
            if (ds.r1BrazilPct < 50 && ds.safetyStockDays < 38 && ds.disruptionDays > 0) {
                mistakes.push(tt('dbf_m3', { days: ds.safetyStockDays, short: ds.disruptionDays }));
            }
            if (ds.ppOption === 'A') mistakes.push(tt('dbf_m1', {}));
            if (ds.ppOption === 'C') mistakes.push(tt('dbf_m2', {}));
            if (ds.acquired && !ds.acqFunded) mistakes.push(tt('dbf_m4', { budget: self._fmt(ds.budgetRemaining) }));
            var insights = [];
            insights.push(mistakes.length ? mistakes[0] : tt('dbf_turning_none', {}));
            for (var mi = 1; mi < mistakes.length; mi++) insights.push(mistakes[mi]);
            insights.push(tt(targetAchieved ? 'dbf_target_met' : 'dbf_target_missed', { exp: self._fmt(finalExposure) }));
            if (ds.disruptionDays > 0 && !(ds.r1BrazilPct < 50 && ds.safetyStockDays < 38)) {
                insights.push(tt('dbf_shortage', { short: ds.disruptionDays }));
            }
            insights.push(tt('dbf_ebitda', { ebitda: self._fmt(finalEbitda), pct: self._fmt(Math.round((finalEbitda - 8230) / 8230 * 1000) / 10) }));
            insights.push(tt('dbf_q1', {}));
            insights.push(tt('dbf_q2', {}));

            return {
                totalScore: overall,
                overallScore: overall,
                score: overall,
                rawPoints: totalScore,
                maxPossibleScore: 100,
                performanceKey: tier,
                performanceLabel: performance,
                finalUsdExposure: finalExposure,
                finalEbitda: finalEbitda,
                targetAchieved: targetAchieved,
                performance: tier,
                insights: insights
            };
        }

        getHint(state, results) {
            var period = state.currentPeriod;
            if (period === 1 && results.roundScore < 20) {
                return window.mySimulation.t('hint_r1_low');
            }
            if (period === 2 && results.budgetExceeded) {
                return window.mySimulation.t('hint_budget');
            }
            if (period === 3 && results.disruptionDays > 10) {
