        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                var titleText = window.mySimulation ? window.mySimulation.t(round.titleKey) : '';
                var briefingText = window.mySimulation ? window.mySimulation.t(round.briefingKey) : '';
                var liveExp = window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState ? window.mySimulation.state.domainState.usdExposure : null;
                briefingText = briefingText.split('{usd}').join(liveExp == null ? '' : this._fmt(liveExp));
                briefEl.innerHTML = '<strong>' + titleText + '</strong><br><br>' + briefingText;
            }

            for (var i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) {
                    panel.style.display = (i === idx) ? 'block' : 'none';
                }
            }

            var resultsPanel = document.getElementById('roundResultsPanel');
            if (resultsPanel) resultsPanel.style.display = 'none';
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new RedGlobalAdapter(), {
            simulationType: 'red_global_supply_chain',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

